describe('Empty State Illustration - Table List', () => {
  beforeEach(() => {
    cy.visit('/table/items');
  });

  it('should display empty state illustration when table has no data', () => {
    // Intercept the API call to return an empty array
    cy.intercept('GET', '/api/table/items', {
      statusCode: 200,
      body: {
        data: [],
        total: 0
      }
    }).as('getEmptyTableData');

    // Trigger the table data load
    cy.get('[data-testid="load-table-button"]').click();

    // Wait for the API response
    cy.wait('@getEmptyTableData');

    // Verify the empty state illustration is visible
    cy.get('[data-testid="empty-state-illustration"]').should('be.visible');

    // Verify the illustration contains the correct message
    cy.get('[data-testid="empty-state-message"]').should('contain', 'No items found');

    // Verify the table body is empty
    cy.get('[data-testid="table-body"]').should('be.visible');
    cy.get('[data-testid="table-row"]').should('not.exist');

    // Verify the empty state action button is present
    cy.get('[data-testid="refresh-button"]').should('be.visible');
  });

  it('should hide empty state illustration when data is loaded', () => {
    // Intercept the API call to return data
    cy.intercept('GET', '/api/table/items', {
      statusCode: 200,
      body: {
        data: [
          { id: 1, name: 'Item 1', status: 'active' },
          { id: 2, name: 'Item 2', status: 'inactive' }
        ],
        total: 2
      }
    }).as('getPopulatedTableData');

    // Trigger the table data load
    cy.get('[data-testid="load-table-button"]').click();

    // Wait for the API response
    cy.wait('@getPopulatedTableData');

    // Verify the empty state illustration is hidden
    cy.get('[data-testid="empty-state-illustration"]').should('not.exist');

    // Verify the table rows are visible
    cy.get('[data-testid="table-row"]').should('have.length', 2);

    // Verify the table contains data
    cy.get('[data-testid="table-row"]').first().should('contain', 'Item 1');
    cy.get('[data-testid="table-row"]').last().should('contain', 'Item 2');

    // Verify the table header is visible
    cy.get('[data-testid="table-header"]').should('be.visible');
  });
});
